            const target = (await Entity.filter({})).find(t => t.name.toLowerCase() === String(value).toLowerCase());
            if (!target) throw new Error('Entity not found: ' + value);
            value = target.id;
        }
        await Entity.set('garden pump', 'state', value);
        return { entity: 'garden pump', property: 'state', value: display };
